users = {"admin": "123456", "alice": "py2026", "bob": "hello"}

for attempt in range(1, 4):
    name = input().strip()
    pwd = input().strip()
    if users.get(name) == pwd:
        print(f"欢迎回来，{name}！（第 {attempt} 次登录成功）")
        break
    else:
        print(f"用户名或密码错误，剩余 {3 - attempt} 次机会")
else:
    print("连续 3 次登录失败，账户已锁定！")

s = input().lower()
cnt = {}
for ch in s:
    if 'a' <= ch <= 'z':
        cnt[ch] = cnt.get(ch, 0) + 1

print("共出现不同字母种数:", len(cnt))
ranked = sorted(cnt.items(), key=lambda kv: -kv[1])
for ch, num in ranked[:3]:
    print(f"{ch}: {num}")
